import { SearchData, RandomizationAlgorithm, CovariateConfig, RepeatedMeasuresConfig, NaPolicy, DEFAULT_NA_POLICY } from './types';
import { QualityLevel, QUALITY_LEVEL_CONFIG } from './configs';
import Papa from 'papaparse';
import { balancedBlockRandomization } from '../algorithms/balancedRandomization';
import { greedyRandomization } from '../algorithms/greedyRandomization';
import { groupAwareRandomization } from '../algorithms/repeatedMeasuresDistribution';

// Utility functions
export function shuffleArray<T>(array: T[]): T[] {
  const shuffled = [...array];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled;
}

/**
 * Generate a covariate key for a search sample, optionally including QC prefix
 * @param search - The search sample
 * @param config - Covariate configuration (treatment covariates and QC/Reference settings)
 * @returns Covariate key string (e.g., "QC|Balb_cJ|Control|0" or "Balb_cJ|Control|0")
 */
/**
 * Get the covariate key for a sample, throwing an error if not set
 * @param sample - The search sample
 * @returns The covariate key (includes QC prefix if applicable)
 * @throws Error if covariateKey is not set
 */
export function getCovariateKey(sample: SearchData): string {
  if (!sample.covariateKey) {
    throw new Error(`covariateKey not set for sample: ${sample.name}`);
  }
  return sample.covariateKey;
}

// Escape any backslash or "|" in a value, so joining values with "|" can't turn
// two different combinations into the same key. Escape backslash before pipe.
function escapeCovariateValue(value: string): string {
  return value.replace(/\\/g, '\\\\').replace(/\|/g, '\\|');
}

/**
 * Key part for a blank cell, kept distinct from a cell that literally says N/A.
 * The marker is a single backslash, which is safe because:
 * - We emit it raw, never through escapeCovariateValue, so it stays a lone backslash.
 * - Escaping a real value doubles every backslash, so a real value never becomes a lone one.
 * - It is not 'N/A', so it also cannot match a folded N/A cell.
 * A lone backslash in a key therefore always means the cell was blank.
 */
export const MISSING_MARKER = '\\'; // '\\' is a JS string literal for one backslash character

/** True when a value is empty or whitespace-only. */
function isBlank(value: string): boolean {
  return value.trim().length === 0;
}

/**
 * True when a value is a candidate for the N/A bucket: blank/whitespace-only, or any case
 * spelling of NA or N/A. Nothing else (None, null, -) counts.
 */
export function isNaType(value: string): boolean {
  if (isBlank(value)) return true;
  const lower = value.toLowerCase();
  return lower === 'na' || lower === 'n/a';
}

/**
 * What a raw covariate value means for grouping and display under the global policy:
 * - value: an ordinary value, or an N/A-type spelling the user chose to keep distinct.
 * - na: folds into the canonical N/A group.
 * - missing: a genuinely-blank cell kept distinct from N/A (uses the missing marker).
 */
export type EffectiveValue =
  | { kind: 'value'; value: string }
  | { kind: 'na' }
  | { kind: 'missing' };

/**
 * Decide, for one raw covariate value under the global policy, what it means. Grouping (the key)
 * and display both go through this one function so they cannot drift. See the na-value-handling
 * design. The literal 'N/A' always folds, regardless of the policy.
 */
export function effectiveValue(raw: string, policy: NaPolicy = DEFAULT_NA_POLICY): EffectiveValue {
  if (!isNaType(raw)) return { kind: 'value', value: raw };
  if (isBlank(raw)) return policy.foldBlank ? { kind: 'na' } : { kind: 'missing' };
  if (raw === 'N/A') return { kind: 'na' };
  return policy.foldSpellings.includes(raw) ? { kind: 'na' } : { kind: 'value', value: raw };
}

/** The key part for an effective value. The missing marker is emitted raw, never escaped. */
function effectiveKeyPart(ev: EffectiveValue): string {
  switch (ev.kind) {
    case 'value': return escapeCovariateValue(ev.value);
    case 'na': return escapeCovariateValue('N/A');
    case 'missing': return MISSING_MARKER;
  }
}

/**
 * The display text for a raw covariate value under the policy. A folded group shows 'N/A', a
 * kept-distinct missing (blank) group shows blank, and an ordinary value shows itself. Group
 * rollups (legend, summary, modal, Excel legend) use this so their labels match the grouping.
 */
export function effectiveDisplayValue(raw: string, policy: NaPolicy = DEFAULT_NA_POLICY): string {
  const ev = effectiveValue(raw, policy);
  switch (ev.kind) {
    case 'value': return ev.value;
    case 'na': return 'N/A';
    case 'missing': return '';
  }
}

export interface NaDetectionResult {
  /**
   * For each column that holds at least one N/A-type value, the distinct spellings found. A
   * blank or whitespace-only cell is recorded as the empty string ''. A non-blank spelling is
   * recorded with its exact text (for example 'na', 'NA', 'N/A'), since grouping is case-exact.
   */
  byColumn: Map<string, Set<string>>;
  /** Union of the distinct N/A-type spellings across all columns, with blank recorded as ''. */
  spellings: Set<string>;
  /** True when at least one column holds two or more distinct N/A-type spellings. */
  hasAmbiguousColumn: boolean;
}

/**
 * Scan every given column across all samples for N/A-type values (blank/whitespace-only, or any
 * case spelling of NA or N/A). Records the distinct spellings per column, their union, and whether
 * any single column mixes two or more. A mixing column is what makes the data ambiguous and
 * surfaces the "N/A values" setting. Runs at upload, before covariate/QC selection, so it treats
 * all columns uniformly. Whitespace-only cells all collapse to the one blank token ''.
 */
export function detectNaTypeValues(samples: SearchData[], columns: string[]): NaDetectionResult {
  const byColumn = new Map<string, Set<string>>();
  const spellings = new Set<string>();
  for (const col of columns) {
    const found = new Set<string>();
    for (const sample of samples) {
      const raw = sample.metadata[col] ?? '';
      if (!isNaType(raw)) continue;
      found.add(isBlank(raw) ? '' : raw);
    }
    if (found.size > 0) {
      byColumn.set(col, found);
      found.forEach(token => spellings.add(token));
    }
  }
  const hasAmbiguousColumn = Array.from(byColumn.values()).some(set => set.size >= 2);
  return { byColumn, spellings, hasAmbiguousColumn };
}

export function buildCovariateKey(
  search: SearchData,
  config: CovariateConfig
): string {
  const { selectedCovariates, qcColumn, selectedQcValues, naPolicy = DEFAULT_NA_POLICY } = config;

  // Build the base covariate key. Each value passes through the policy so a blank cell, a
  // literal N/A, and folded spellings all resolve to the right key part.
  const baseKey = selectedCovariates
    .map(cov => effectiveKeyPart(effectiveValue(search.metadata[cov] ?? '', naPolicy)))
    .join('|');

  // Check if this sample is a QC sample and QC column is not in covariates
  if (qcColumn && selectedQcValues && selectedQcValues.length > 0
    && !selectedCovariates.includes(qcColumn)) {
    const sampleValue = search.metadata[qcColumn];
    const isQC = sampleValue && selectedQcValues.includes(sampleValue);

    // Prepend QC value if sample is QC and QC column is not a covariate. The prepended value
    // goes through the same policy so it can't drift from the covariate parts.
    if (isQC) {
      return `${effectiveKeyPart(effectiveValue(sampleValue, naPolicy))}|${baseKey}`;
    }
  }

  return baseKey;
}

/**
 * Sort covariate combinations by count (descending), then alphabetically
 * @param combinations - Array of combination keys to sort
 * @param counts - Map of combination keys to their counts
 * @returns Sorted array of combination keys
 */
export function sortCombinationsByCountAndName(
  combinations: string[],
  counts: Map<string, number>
): string[] {
  return [...combinations].sort((a, b) => {
    const countA = counts.get(a) || 0;
    const countB = counts.get(b) || 0;

    // Sort by count descending
    if (countB !== countA) {
      return countB - countA;
    }

    // If counts are equal, sort alphabetically
    return a.localeCompare(b);
  });
}

/**
 * Calculate appropriate text color (white or black) based on background color luminance
 * Uses WCAG formula for relative luminance calculation
 */
export function getTextColorForBackground(hexColor: string): string {
  // Remove # if present
  const hex = hexColor.replace('#', '');

  // Convert to RGB
  const r = parseInt(hex.substring(0, 2), 16);
  const g = parseInt(hex.substring(2, 4), 16);
  const b = parseInt(hex.substring(4, 6), 16);

  // Calculate relative luminance using WCAG formula
  const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255;

  // Return white for dark backgrounds, black for light backgrounds
  return luminance > 0.5 ? '#000' : '#fff';
}

export function groupByCovariates(searches: SearchData[], selectedCovariates: string[]): Map<string, SearchData[]> {
  const groups = new Map<string, SearchData[]>();

  searches.forEach(search => {
    // covariateKey should already be set by processMetadata
    if (!search.covariateKey) {
      throw new Error(`treatmentKey not set for sample: ${search.name}`);
    }
    const key = search.covariateKey;
    if (!groups.has(key)) {
      groups.set(key, []);
    }
    groups.get(key)!.push(search);
  });

  return groups;
}


// Main randomization function with algorithm selection
export function randomizeSearches(
  searches: SearchData[],
  selectedCovariates: string[],
  algorithm: RandomizationAlgorithm = 'balanced',
  keepEmptyInLastPlate: boolean = true,
  numRows: number = 8,
  numColumns: number = 12,
  repeatedMeasuresConfig?: RepeatedMeasuresConfig,
  naPolicy: NaPolicy = DEFAULT_NA_POLICY
): {
  plates: (SearchData | undefined)[][][];
  plateAssignments?: Map<number, SearchData[]>;
} {
  // When a subject column is set, use group-aware randomization
  if (repeatedMeasuresConfig?.subjectColumn) {
    return groupAwareRandomization(
      searches,
      selectedCovariates,
      repeatedMeasuresConfig,
      keepEmptyInLastPlate,
      numRows,
      numColumns,
      naPolicy
    );
  }

  switch (algorithm) {
    case 'balanced':
      return balancedBlockRandomization(searches, selectedCovariates, keepEmptyInLastPlate, numRows, numColumns);
    case 'greedy':
    default:
      return greedyRandomization(searches, selectedCovariates);
  }
}


/**
 * Set the covariate key and QC flag on each sample, based on the chosen settings.
 * State-independent: depends only on its arguments, not component state. App.tsx's
 * processMetadata and the layout import both go through this so the derivation cannot drift.
 * @param searches - Samples to annotate (mutated in place)
 * @param config - Covariate configuration (treatment covariates and QC/Reference settings)
 */
export function buildProcessedSearches(
  searches: SearchData[],
  config: CovariateConfig
): void {
  const { selectedCovariates, qcColumn, selectedQcValues, naPolicy } = config;
  searches.forEach(search => {
    let isQC = false;
    if (qcColumn && selectedQcValues && selectedQcValues.length > 0) {
      const sampleValue = search.metadata[qcColumn];
      if (sampleValue && selectedQcValues.includes(sampleValue)) {
        isQC = true;
      }
    }
    search.isQC = isQC;
    search.covariateKey = buildCovariateKey(search, {
      selectedCovariates,
      qcColumn,
      selectedQcValues,
      naPolicy,
    });
  });
}

/**
 * Build the placement CSV table (one row per sample: id column, metadata, plate, well).
 * Shared by downloadCSV and the layout export so the two can never drift.
 */
export function buildPlacementCsv(
  searches: SearchData[],
  randomizedPlates: (SearchData | undefined)[][][],
  idColumn: string
): string {
  return Papa.unparse(
    searches.map((search) => ({
      [idColumn]: search.name, // Use the selected ID column name
      ...search.metadata,
      plate: getPlateNumber(search.name, randomizedPlates),
      well: getWell(search.name, randomizedPlates),
    })),
    { header: true }
  );
}

// Updated to accept idColumn parameter instead of hardcoding "search name"
export function downloadCSV(
  searches: SearchData[],
  randomizedPlates: (SearchData | undefined)[][][],
  idColumn: string,
  inputFileName?: string
) {
  const csv = buildPlacementCsv(searches, randomizedPlates, idColumn);

  // Generate output filename based on input filename
  let outputFileName = 'randomized_searches_octopus.csv';
  if (inputFileName) {
    const baseName = inputFileName.replace(/\.[^/.]+$/, ''); // Remove extension
    outputFileName = `${baseName}_octopus.csv`;
  }

  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const link = document.createElement('a');
  const url = URL.createObjectURL(blob);
  link.setAttribute('href', url);
  link.setAttribute('download', withTimestamp(outputFileName));
  link.style.visibility = 'hidden';
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url); // Avoid leaking the object URL on repeated downloads.
}

/**
 * Format a date as `YYYY-MM-DD_HH-mm-ss` in local time, for use in a download filename.
 * Uses only filename-safe characters (digits, hyphens, underscore).
 */
export function formatTimestampForFilename(date: Date): string {
  const pad = (n: number) => String(n).padStart(2, '0');
  return (
    `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}` +
    `_${pad(date.getHours())}-${pad(date.getMinutes())}-${pad(date.getSeconds())}`
  );
}

/**
 * Insert a `_YYYY-MM-DD_HH-mm-ss` timestamp before the final extension of a download
 * filename, so repeated exports do not overwrite one another. A name without an extension
 * gets the timestamp appended. Used for every Octopus export (CSV, Excel, layout, sequence).
 */
export function withTimestamp(filename: string, date: Date = new Date()): string {
  const stamp = formatTimestampForFilename(date);
  const dot = filename.lastIndexOf('.');
  if (dot <= 0) return `${filename}_${stamp}`;
  return `${filename.slice(0, dot)}_${stamp}${filename.slice(dot)}`;
}

/**
 * Build the base name for a saved layout (before the timestamp) from the currently loaded
 * file's name. A saved layout is named `<base>_octopus_layout_<timestamp>.json`, so when the
 * loaded file is itself a saved layout, the `_octopus_layout` suffix and its timestamp are
 * stripped first. Without this, re-saving a loaded layout stacks the suffix and timestamp
 * (e.g. `foo_octopus_layout_<stamp>_octopus_layout_<stamp>.json`). An empty/absent name yields
 * the default `octopus_layout.json`. The timestamp pattern matches formatTimestampForFilename.
 */
export function buildLayoutFileName(selectedFileName?: string): string {
  if (!selectedFileName) return 'octopus_layout.json';
  let base = selectedFileName.replace(/\.[^/.]+$/, ''); // drop the extension
  // Strip any stacked `_octopus_layout(_<timestamp>)` suffixes left by a previous save.
  const suffix = /_octopus_layout(_\d{4}-\d{2}-\d{2}_\d{2}-\d{2}-\d{2})?$/;
  while (suffix.test(base)) base = base.replace(suffix, '');
  if (!base) return 'octopus_layout.json';
  return `${base}_octopus_layout.json`;
}

export function getPlateNumber(searchName: string, randomizedPlates: (SearchData | undefined)[][][]) {
  for (let plateIndex = 0; plateIndex < randomizedPlates.length; plateIndex++) {
    const plate = randomizedPlates[plateIndex];
    for (let rowIndex = 0; rowIndex < plate.length; rowIndex++) {
      const row = plate[rowIndex];
      if (row.find((search) => search?.name === searchName)) {
        return plateIndex + 1;
      }
    }
  }
  return '';
}

export function getWell(searchName: string, randomizedPlates: (SearchData | undefined)[][][]): string {
  for (let plateIndex = 0; plateIndex < randomizedPlates.length; plateIndex++) {
    const plate = randomizedPlates[plateIndex];
    for (let rowIndex = 0; rowIndex < plate.length; rowIndex++) {
      const row = plate[rowIndex];
      for (let columnIndex = 0; columnIndex < row.length; columnIndex++) {
        if (row[columnIndex]?.name === searchName) {
          const rowLabel = String.fromCharCode(65 + rowIndex); // A, B, C...
          const colLabel = (columnIndex + 1).toString().padStart(2, '0'); // 01, 02, 03...
          return `${rowLabel}${colLabel}`;
        }
      }
    }
  }
  return '';
}

/**

 * Get color for quality score based on standardized thresholds
 * @param score - Quality score (0-100)
 * @returns Hex color code
 */
export const getQualityColor = (score: number): string => {
  return getQualityLevelColor(getQualityLevel(score));
};

/**
 * Get color for quality level string
 * @param level - Quality level ('excellent', 'good', 'fair', 'poor', 'bad')
 * @returns Hex color code
 */
export const getQualityLevelColor = (level: QualityLevel): string => {
  return QUALITY_LEVEL_CONFIG[level].color;
};

// Presorted quality levels by descending lowScore (highest to lowest) - computed once at module load
const QUALITY_LEVELS_BY_SCORE = Object.entries(QUALITY_LEVEL_CONFIG)
  .sort(([, a], [, b]) => b.lowScore - a.lowScore);

/**
 * Get quality level for a given score
 * @param score - Quality score (0-100)
 * @returns Quality level
 */
export const getQualityLevel = (score: number): QualityLevel => {
  // Round to 1 decimal place to match display formatting
  const roundedScore = Math.round(score * 10) / 10;

  // Find the first quality level where score >= lowScore
  for (const [levelKey, config] of QUALITY_LEVELS_BY_SCORE) {
    if (roundedScore >= config.lowScore) {
      return levelKey as QualityLevel;
    }
  }

  // Fallback to 'bad' if no match found (should never happen)
  return 'bad';
};

/**
 * Format a quality score for display with consistent decimal precision
 * @param score - Quality score (0-100)
 * @returns Formatted score string with 1 decimal place
 */
export const formatScore = (score: number): string => {
  return score.toFixed(1);
};

/**
 * Get compact quality level (first letter) for a given score
 * @param score - Quality score (0-100)
 * @returns Single uppercase letter representing quality level
 */
export const getCompactQualityLevel = (score: number): string => {
  return getCompactQualityLevelFromString(getQualityLevel(score));
};

/**
 * Get compact quality level from quality level string
 * @param level - Quality level string
 * @returns Single uppercase letter representing quality level
 */
export const getCompactQualityLevelFromString = (level: QualityLevel): string => {
  return QUALITY_LEVEL_CONFIG[level].shortLabel;
};

/**
 * Get all quality levels with their score ranges, badges, and descriptions
 * @returns Array of quality level information sorted by score (best to worst)
 */
export const getAllQualityLevels = () => {
  return QUALITY_LEVELS_BY_SCORE.map(([levelKey, config]) => ({
    range: `${config.lowScore}-${config.highScore}`,
    level: levelKey as QualityLevel,
    badge: config.shortLabel,
    description: config.name,
    color: config.color
  }));
};
